{"title":"System log volume over time","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "system-logs-*",
      "body": {
        "size": 0,
        "aggs": {
          "timeline": {
            "date_histogram": {
              "field": "@timestamp",
              "fixed_interval": "1m",
              "min_doc_count": 0,
              "extended_bounds": {
                "min": {
                  "%timefilter%": "min"
                },
                "max": {
                  "%timefilter%": "max"
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.timeline.buckets"
    }
  },
  "mark": {
    "type": "area",
    "line": true,
    "color": "#54B399"
  },
  "encoding": {
    "x": {
      "field": "key",
      "type": "temporal",
      "axis": {
        "title": "Time"
      }
    },
    "y": {
      "field": "doc_count",
      "type": "quantitative",
      "axis": {
        "title": "Log events"
      }
    },
    "tooltip": [
      {
        "field": "key_as_string",
        "type": "temporal",
        "title": "Time"
      },
      {
        "field": "doc_count",
        "type": "quantitative",
        "title": "Events"
      }
    ]
  }
}"}}

